// SetPlan of the tenant to the related item.
// Sets o.R.Plan to related.
// Adds o to related.R.Tenants.
func (o *Tenant) SetPlan(ctx context.Context, exec boil.ContextExecutor, insert bool, related *Plan) error {
	var err error
	if insert {
		if err = related.Insert(ctx, exec, boil.Infer()); err != nil {
			return errors.Wrap(err, "failed to insert into foreign table")
		}
	}

	updateQuery := fmt.Sprintf(
		"UPDATE \"tenants\" SET %s WHERE %s",
		strmangle.SetParamNames("\"", "\"", 1, []string{"plan_id"}),
		strmangle.WhereClause("\"", "\"", 2, tenantPrimaryKeyColumns),
	)
	values := []any{related.ID, o.ID}

	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, updateQuery)
		fmt.Fprintln(writer, values)
	}
	if _, err = exec.ExecContext(ctx, updateQuery, values...); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	o.PlanID = related.ID
	if o.R == nil {
		o.R = &tenantR{
			Plan: related,
		}
	} else {
		o.R.Plan = related
	}

	if related.R == nil {
		related.R = &planR{
			Tenants: TenantSlice{o},
		}
	} else {
		related.R.Tenants = append(related.R.Tenants, o)
	}

	return nil
}

